  H = H_1 → Erdos643.AllStarDeletion.Charge H = Erdos643.AllStarDeletion.Charge H_1

∀ {X : Type u_1} {Y : Type u_2} [inst : Fintype X] [inst_1 : Fintype Y] {inst_2 : DecidableEq X}
  [inst_3 : DecidableEq X] [inst_4 : DecidableEq Y] (H H_1 : Erdos643.AllStarDeletion.Flags X Y),
  H = H_1 → Erdos643.AllStarDeletion.YChargePairs H = Erdos643.AllStarDeletion.YChargePairs H_1

∀ {X : Type u_1} {Y : Type u_2} [inst : Fintype X] [inst_1 : Fintype Y] [inst_2 : DecidableEq X]
  [inst_3 : DecidableEq Y] {H : Erdos643.AllStarDeletion.Flags X Y} (g : Erdos643.AllStarDeletion.Charge H → Y) (y : Y),
  Erdos643.AllStarDeletion.bucket g y = {c | g c = y}

∀ {X : Type u_1} {Y : Type u_2} [inst : DecidableEq Y] (y : Y) (a b : X ⊕ Y),
  (match a, b with
    | Sum.inl x, Sum.inr z => {(x, {y, z})}
    | Sum.inr z, Sum.inl x => {(x, {y, z})}
    | x, x_1 => ∅) =
    match b, a with
    | Sum.inl x, Sum.inr z => {(x, {y, z})}
    | Sum.inr z, Sum.inl x => {(x, {y, z})}
    | x, x_1 => ∅

∀ {X : Type u_1} {Y : Type u_2} [inst : Fintype X] [inst_1 : Fintype Y] {inst_2 : DecidableEq X}
  [inst_3 : DecidableEq X] [inst_4 : DecidableEq Y] (H H_1 : Erdos643.AllStarDeletion.Flags X Y),
  H = H_1 → Erdos643.AllStarDeletion.yChargeGraph H = Erdos643.AllStarDeletion.yChargeGraph H_1

∀ {V : Type u_1} [Fintype V] [inst : DecidableEq V] {H : Erdos643.HypergraphBasics.TripleSystem V} {x : V}
  {A Q : Finset V},
  Erdos643.K5Cleaning.K5Support H A → Q ⊆ A → Q.card = 2 → 2 ≤ (Erdos643.K5Cleaning.extensionPairs H x A Q).card

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] {H : Erdos643.HypergraphBasics.TripleSystem V} {x y : V}
  {E : Finset V},
  E ∈ Erdos643.K5Cleaning.orientedEdges H x y ↔ ∃ Q A, Erdos643.K5Cleaning.SecondaryWitness H x y Q A ∧ E = insert x Q

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] {H : Erdos643.HypergraphBasics.TripleSystem V}
  {E : Finset V},
  E ∈ Erdos643.K5Cleaning.secondaryTriples H ↔ E ∈ H ∧ ∃ A ∈ Erdos643.K5Cleaning.supports H, (E ∩ A).card = 2

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] (H : Erdos643.HypergraphBasics.TripleSystem V) (x y : V),
  Erdos643.K5Cleaning.orientedEdges H x y =
    {E ∈ H | ∃ Q A, Erdos643.K5Cleaning.SecondaryWitness H x y Q A ∧ E = insert x Q}

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] (H : Erdos643.HypergraphBasics.TripleSystem V),
  Erdos643.K5Cleaning.secondaryPairs H =
    {S ∈ Erdos643.K5Cleaning.Bpairs H | ∃ x y, S = {x, y} ∧ ∃ Q A, Erdos643.K5Cleaning.SecondaryWitness H x y Q A}

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] {H : Erdos643.HypergraphBasics.TripleSystem V}
  (E : Finset V),
  2 ≤ (Erdos643.K5Cleaning.incidentPairs H E).card → ¬0 < (Erdos643.K5Cleaning.incidentPairs H E).card → False

∀ {V : Type u_1} [inst : DecidableEq V] {H : Erdos643.HypergraphBasics.TripleSystem V} {T P : Finset V},
  Erdos643.PrivatePairs.Pi H T P →
    ∀ {a b c p : V}, T = {a, b, c} → a ≠ b → a ≠ c → b ≠ c → p ∈ P → Erdos643.HypergraphBasics.CommonPair H a b {p, c}

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] (T : Finset (V × Finset V)),
  Erdos643.ProjectionBridge.XCharges T =
    {S ∈ Finset.powersetCard 2 Finset.univ | ∃ x y, S = {x, y} ∧ Erdos643.ProjectionBridge.XActive T x y}

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] (T : Finset (V × Finset V)),
  Erdos643.ProjectionBridge.YCharges T =
    {S ∈ Finset.powersetCard 2 Finset.univ | ∃ u v, S = {u, v} ∧ Erdos643.ProjectionBridge.YDiag T u v}

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] {H : Erdos643.HypergraphBasics.TripleSystem V}
  {T : Finset V},
  2 ≤ (Erdos643.TriangleCleanup.fullKernel H T).card → ¬0 < (Erdos643.TriangleCleanup.fullKernel H T).card → False

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] {H : Erdos643.HypergraphBasics.TripleSystem V}
  {T : Finset V},
  T ∈ Erdos643.TriangleCleanup.roots H → Erdos643.PrivatePairs.Pi H T (Erdos643.TriangleCleanup.fullKernel H T)

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] {H : Erdos643.HypergraphBasics.TripleSystem V}
  {T : Finset V},
  1 < (Erdos643.TriangleCleanup.fullKernel H T).card → ¬2 ≤ (Erdos643.TriangleCleanup.fullKernel H T).card → False

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] {H : Erdos643.HypergraphBasics.TripleSystem V}
  {T P : Finset V},
  Erdos643.PrivatePairs.Pi H T P → Erdos643.PrivatePairs.privatePairs T P ⊆ Erdos643.TriangleCleanup.Dpairs H

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] (H : Erdos643.HypergraphBasics.TripleSystem V),
  Erdos643.TriangleCleanup.roots H =
    {T ∈ Finset.powersetCard 3 Finset.univ | 2 ≤ (Erdos643.TriangleCleanup.fullKernel H T).card}
